import{_ as s,C as i,o as t,c as d,a2 as a,b as r,w as o,a as l,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const w=JSON.parse('{"title":"Command Reference","description":"The /nitrocord admin command (alias /nc) — protection statistics, live config reload, manual firewall add/remove, and anti-VPN diagnostics. Syntax, example output and day-to-day workflows.","frontmatter":{"title":"Command Reference","description":"The /nitrocord admin command (alias /nc) — protection statistics, live config reload, manual firewall add/remove, and anti-VPN diagnostics. Syntax, example output and day-to-day workflows."},"headers":[],"relativePath":"nitrocord/user-guide/cli.md","filePath":"nitrocord/user-guide/cli.md","lastUpdated":1785341162000}'),h={name:"nitrocord/user-guide/cli.md"};function g(m,e,u,f,v,b){const n=i("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a(`<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>NitroCord ships one administration command, <code>/nitrocord</code> (alias <code>/nc</code>), registered by the proxy itself. It works identically from the server console and in-game, and covers the four things you need while watching the proxy: protection statistics, configuration reloads, manual firewall entries, and anti-VPN diagnostics.</p><div class="info custom-block"><p class="custom-block-title">Permission</p><p>Every subcommand requires <code>nitrocord.admin</code>. The console always has it; in-game, grant it with your permission plugin (e.g. <code>lpv user &lt;you&gt; permission set nitrocord.admin</code>). Senders without the permission see the configured <code>messages.no-permission</code> message, not Velocity&#39;s generic unknown-command error.</p></div><p>Running <code>/nitrocord</code> with no arguments prints the subcommand list:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord » commands</span></span>
<span class="line"><span>  /nitrocord stats - show protection statistics</span></span>
<span class="line"><span>  /nitrocord reload - reload the configuration</span></span>
<span class="line"><span>  /nitrocord firewall add &lt;ip&gt; - add an address to the firewall</span></span>
<span class="line"><span>  /nitrocord firewall remove &lt;ip&gt; - remove an address from the firewall</span></span>
<span class="line"><span>  /nitrocord antivpn test &lt;ip&gt; - test an address against the anti-VPN checks</span></span></code></pre></div><p>All output goes through the messages in <code>nitrocord.toml</code>, so the pink/white theme shown here is just the default — recolor or reword every line under <code>[messages]</code> and <code>[theme]</code>.</p><hr><h2 id="nitrocord-stats" tabindex="-1"><code>/nitrocord stats</code> <a class="header-anchor" href="#nitrocord-stats" aria-label="Permalink to &quot;\`/nitrocord stats\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nc stats</span></span></code></pre></div><p>Prints the global protection counters, all measured since the proxy started:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord » Protection statistics</span></span>
<span class="line"><span>  Total pings: 1284407</span></span>
<span class="line"><span>  Pings per second: 31</span></span>
<span class="line"><span>  Total connections: 84312</span></span>
<span class="line"><span>  Connections per second: 47</span></span>
<span class="line"><span>  Blocked connections: 3918</span></span>
<span class="line"><span>  Firewalled addresses: 261</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Line</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Total pings</code></td><td>Server list pings received since start.</td></tr><tr><td><code>Pings per second</code></td><td>Pings within the current one-second window.</td></tr><tr><td><code>Total connections</code></td><td>Login connections received since start.</td></tr><tr><td><code>Connections per second</code></td><td>Connections within the current one-second window — the value attack mode watches (engages at <code>[attack] activate-connections-per-second</code>, default 40).</td></tr><tr><td><code>Blocked connections</code></td><td>Connections or players denied by any protection check since start.</td></tr><tr><td><code>Firewalled addresses</code></td><td>Addresses added to the firewall since start (automatic bans and <code>/nc firewall add</code>).</td></tr></tbody></table><p><strong>When to use:</strong> the first command you run when something feels off. During an attack, <code>Connections per second</code> and the two blocked counters climb in real time; in quiet periods they confirm the proxy sees normal traffic.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Counters reset on restart. The header and line format are the <code>stats-header</code> and <code>stats-line</code> messages in <code>nitrocord.toml</code> if you want to retheme them.</p></div><hr><h2 id="nitrocord-reload" tabindex="-1"><code>/nitrocord reload</code> <a class="header-anchor" href="#nitrocord-reload" aria-label="Permalink to &quot;\`/nitrocord reload\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nc reload</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord » Configuration reloaded.</span></span></code></pre></div><p>Re-reads <code>nitrocord.toml</code> and <code>protection.toml</code> from disk and re-applies them to the stateful protection services (GeoIP, anti-VPN, MOTD cache, verified-IP whitelist). A broken file falls back to the bundled defaults with an error in the console — reload never crashes the proxy.</p><p><strong>Applies immediately, no restart needed:</strong></p><ul><li>Every threshold, toggle and list in <code>protection.toml</code> — rate limits, attack-mode thresholds, violation strikes, packet scoring, check toggles, and <code>ban-time-seconds</code> for <strong>new</strong> bans</li><li>Branding, theme colors and every message in <code>nitrocord.toml</code></li><li>GeoIP — a new MaxMind key, country blacklist or database setting</li><li>Anti-VPN — blocklists, online-check keys, cache settings</li><li>MOTD caching, custom MOTDs and fake-player settings</li><li>Verified-IP whitelist settings</li></ul><p><strong>Requires a proxy restart:</strong></p><ul><li><code>license-key</code> — the license is verified once at startup</li><li><code>firewall.ipset</code> — the kernel ipset/iptables integration is set up once at startup</li><li>Anything in <code>velocity.toml</code> — that file is not NitroCord&#39;s; use <code>/velocity reload</code> for it</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>/velocity reload</code> also reloads both NitroCord TOMLs (it calls the same reload path before firing Velocity&#39;s <code>ProxyReloadEvent</code>), so either command works for NitroCord config changes.</p></div><hr><h2 id="nitrocord-firewall-add-ip" tabindex="-1"><code>/nitrocord firewall add &lt;ip&gt;</code> <a class="header-anchor" href="#nitrocord-firewall-add-ip" aria-label="Permalink to &quot;\`/nitrocord firewall add &lt;ip&gt;\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nc firewall add 203.0.113.50</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord » 203.0.113.50 added to the firewall.</span></span></code></pre></div><p>Manually bans an address, using the exact same mechanism as automatic bans:</p><ul><li>The address is banned <strong>in memory</strong> for <code>[firewall] ban-time-seconds</code> (default <code>60</code>) — change that key in <code>protection.toml</code> and <code>/nc reload</code> to adjust it.</li><li>When the <a href="/pingless-studios-docs/nitrocord/getting-started/installation">kernel firewall</a> is active (Linux, root, <code>ipset</code>/<code>iptables</code>, <code>firewall.ipset = true</code>) and the address is IPv4, an <code>ipset</code> entry with the same timeout is queued, so packets are dropped before they reach the proxy at all.</li><li>The ban is counted in <code>/nc stats</code>, written to the log with the reason <code>manual</code>, and announced to plugins through <code>NitroFirewallEvent</code>.</li></ul>`,30)),(t(),r(p,null,{default:o(()=>[c(n,{id:"mermaid-192",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%2Fnc%20firewall%20add%20203.0.113.50%22%5D%20--%3E%20B%7BValid%20IP%20literal%3F%7D%0A%20%20%20%20B%20--%3E%7Cno%7C%20U%5BShow%20usage%5D%0A%20%20%20%20B%20--%3E%7Cyes%7C%20C%7BLoopback%20or%20in%20firewall.whitelist%3F%7D%0A%20%20%20%20C%20--%3E%7Cyes%7C%20N%5BNo-op%5D%0A%20%20%20%20C%20--%3E%7Cno%7C%20D%5B%22In-memory%20ban%20for%20ban-time-seconds%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Stats%20%2B%20log%20%2B%20NitroFirewallEvent%22%5D%0A%20%20%20%20D%20--%3E%20F%7BKernel%20firewall%20active%20and%20IPv4%3F%7D%0A%20%20%20%20F%20--%3E%7Cyes%7C%20G%5B%22ipset%20entry%20with%20same%20timeout%22%5D%0A%20%20%20%20F%20--%3E%7Cno%7C%20H%5B%22In-memory%20only%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<div class="warning custom-block"><p class="custom-block-title">IP literals only</p><p>The argument must be a literal IP address — hostnames are rejected (the command never resolves DNS) and invalid input prints the usage list. Loopback addresses and IPs in <code>[firewall] whitelist</code> can never be firewalled; the confirmation is shown regardless, but the firewall itself skips them. Bans always expire after <code>ban-time-seconds</code> — there is no permanent-ban subcommand.</p></div><hr><h2 id="nitrocord-firewall-remove-ip" tabindex="-1"><code>/nitrocord firewall remove &lt;ip&gt;</code> <a class="header-anchor" href="#nitrocord-firewall-remove-ip" aria-label="Permalink to &quot;\`/nitrocord firewall remove &lt;ip&gt;\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nc firewall remove 203.0.113.50</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord » 203.0.113.50 removed from the firewall.</span></span></code></pre></div><p>Lifts a ban early: clears the in-memory state and, when the kernel firewall is active, queues the <code>ipset</code> removal. The removal is announced to plugins through <code>NitroFirewallEvent</code>.</p><p><strong>When to use:</strong> false positives — a legitimate player firewalled by an aggressive check, or an address you banned by mistake. If a source keeps getting banned legitimately, exempt it in <code>[firewall] whitelist</code> instead of repeatedly removing it.</p><hr><h2 id="nitrocord-antivpn-test-ip" tabindex="-1"><code>/nitrocord antivpn test &lt;ip&gt;</code> <a class="header-anchor" href="#nitrocord-antivpn-test-ip" aria-label="Permalink to &quot;\`/nitrocord antivpn test &lt;ip&gt;\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nc antivpn test 203.0.113.50</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord » anti-vpn test for 203.0.113.50</span></span>
<span class="line"><span>  offline blocklist: clean</span></span>
<span class="line"><span>  cached verdict: none</span></span>
<span class="line"><span>  overall: VPN/proxy</span></span>
<span class="line"><span>  getipintel: VPN/proxy</span></span>
<span class="line"><span>  proxycheck: VPN/proxy</span></span>
<span class="line"><span>  iphub: not configured (abstained)</span></span>
<span class="line"><span>  vpnapi: clean</span></span>
<span class="line"><span>  ipqualityscore: rate-limited (abstained)</span></span></code></pre></div><p>Runs the anti-VPN stack against one address and prints every layer&#39;s answer:</p><table tabindex="0"><thead><tr><th>Line</th><th>Meaning</th></tr></thead><tbody><tr><td><code>offline blocklist</code></td><td>Whether the address is on the downloaded blocklists (<code>BLOCKED</code> or <code>clean</code>).</td></tr><tr><td><code>cached verdict</code></td><td>The remembered verdict, if any (<code>VPN</code>, <code>clean</code>, or <code>none</code>) — this is what the accept-time gate acts on.</td></tr><tr><td><code>overall</code></td><td>The full verdict of the online check: the cached answer if known, otherwise a live provider quorum.</td></tr><tr><td>one line per provider</td><td>The provider&#39;s own answer from a fresh parallel query: <code>VPN/proxy</code>, <code>clean</code>, or an abstention (<code>rate-limited</code>, <code>not configured</code>, <code>connection error</code>, <code>unintelligible answer</code>).</td></tr></tbody></table><p>The first two lines print immediately; <code>overall</code> and the per-provider lines arrive a moment later once the parallel provider queries finish. The fresh per-provider votes are settled into the verdict cache and the persisted journal exactly like a post-login recheck, so the test also refreshes what future joins will see.</p><p><strong>When to use:</strong> the tool for &quot;was this player really on a VPN?&quot; — run it against the address from a <code>Blocked &lt;ip&gt; (&lt;name&gt;): VPN/proxy</code> log line before whitelisting anyone, and against a known-VPN address after entering API keys to confirm your providers actually answer. A provider that keeps showing an abstention is misconfigured or out of quota (three abstentions in a row also log a console warning).</p><div class="tip custom-block"><p class="custom-block-title">No providers configured, no breakdown</p><p>With every provider key empty, the online check has nothing to query: the command prints the blocklist and cached verdicts, an <code>overall: clean</code> fail-open answer, and no per-provider lines. The same happens for loopback and <code>[antivpn] whitelist</code>ed addresses, which always pass. And when anti-VPN itself is off (or the license is inactive), the command says so: every check fails open.</p></div><hr><h2 id="console-vs-in-game" tabindex="-1">Console vs in-game <a class="header-anchor" href="#console-vs-in-game" aria-label="Permalink to &quot;Console vs in-game&quot;">​</a></h2><p>Both work the same; the differences are practical:</p><ul><li><strong>Console</strong> — always permitted, no permission plugin needed. Best during an attack, when you may not be able to join. Type the command without the slash: <code>nitrocord stats</code>.</li><li><strong>In-game</strong> — needs <code>nitrocord.admin</code>; output rendered in the pink/white theme. Best for watching <code>stats</code> while playing or testing checks with a second account.</li></ul><hr><h2 id="common-workflows" tabindex="-1">Common workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common workflows&quot;">​</a></h2><h3 id="investigating-an-ongoing-attack" tabindex="-1">Investigating an ongoing attack <a class="header-anchor" href="#investigating-an-ongoing-attack" aria-label="Permalink to &quot;Investigating an ongoing attack&quot;">​</a></h3><ol><li>The console logs <code>attack mode engaged</code> once the connection rate crosses the threshold — or you notice join lag.</li><li><code>nitrocord stats</code> — watch <code>Connections per second</code>, <code>Blocked connections</code> and <code>Firewalled addresses</code> climb. If blocked ≈ total, protection is absorbing the flood.</li><li>Check <code>logs/latest.log</code> for <code>Firewalled &lt;ip&gt; for 60 seconds: &lt;reason&gt;</code> and <code>Blocked &lt;ip&gt; (&lt;name&gt;): &lt;reason&gt;</code> lines to see which checks are firing.</li><li>For an offender that keeps retrying without tripping an automatic ban: <code>nitrocord firewall add &lt;ip&gt;</code>.</li><li>Re-run <code>stats</code>; when <code>Connections per second</code> drops back under the threshold, attack mode disengages after <code>[attack] deactivate-delay-seconds</code> (default 60) quiet seconds.</li></ol><h3 id="handling-a-false-positive" tabindex="-1">Handling a false positive <a class="header-anchor" href="#handling-a-false-positive" aria-label="Permalink to &quot;Handling a false positive&quot;">​</a></h3><ol><li>A player reports being kicked — find the <code>Blocked &lt;ip&gt; (&lt;name&gt;): &lt;reason&gt;</code> line in the log to identify the check and reason.</li><li><code>nitrocord firewall remove &lt;ip&gt;</code> if they were firewalled.</li><li>Tune the responsible check in <code>protection.toml</code> (or exempt the address in the relevant <code>whitelist</code> list), then <code>nitrocord reload</code>.</li></ol><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/nitrocord/user-guide/api">Plugin API</a> — react to verdicts, firewall bans and attack mode from your own Velocity plugin.</li><li><a href="/pingless-studios-docs/nitrocord/getting-started/quick-start">Quick Start</a> — the five <code>protection.toml</code> tweaks most admins make first.</li><li><a href="/pingless-studios-docs/nitrocord/getting-started/installation">Installation</a> — kernel firewall prerequisites and post-install verification.</li></ul>`,29))])}const y=s(h,[["render",g]]);export{w as __pageData,y as default};
